    eapply (sr_ecall_MS L S Zr _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F 0x086c58 fc None m2 msF2 mo2 Q OK2 VIS2 ecall_86dd8).
    clear OK2 VIS2. intros msF3 OK3 VIS3 HS3.
    (* [comment removed for export] *)
    assert (NZ : page_round_up_Z (bv_unsigned (wz 262144)) = 262144) by (vm_compute; reflexivity).
    pose proof (same_but_materialized_trans _ _ _ SBM1 SBM2) as SBM.
    eapply (sr_mmap_commit_MS L S Zr _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F 0x086c58 fc None m2 false msF3 mo2 Q OK3 VIS3 eq_refl);
      rewrite ?NZ, ?(same_but_materialized_vmmaps _ _ SBM), ?(same_but_materialized_eager _ _ SBM); unfold wz; rewrite ?unsigned_lit by (first [clear - BEG2 BEG1 BNDL BND HI; lia | lia]).
    { apply wz_ne0. clear; lia. }
    { reflexivity. } { reflexivity. } { reflexivity. } { reflexivity. }
    { rewrite ATOP. clear - BEG1 BEG2 BND BNDL; try acb. lia. }
    { unfold page_size. rewrite BQ. clear. Z.div_mod_to_equations. lia. }
    { clear - BEG1 BND BNDL; try acb. lia. }
    (* [region_free] at [rbeg + mu], a window inside the primary region: [RESF] takes the [AHI_LO]
